type Message = { kind: "order"; id: string } | { kind: "ping"; seq: number };
type Handler = (m: Message) => Promise<void>;

const handlers = {
  order: async (m) => dispatchOrder(m),
  ping:  async (m) => pong(m),
} satisfies Record<Message["kind"], Handler>;

let live: Record<Message["kind"], Handler> = handlers;   // swap on rule update
export const route = (m: Message) => live[m.kind](m);
